package com.chatsystem.user.controller.report;import com.chatsystem.shared.model.SpamReport;import com.chatsystem.shared.service.ReportService;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.ReportCell;import javafx.collections.FXCollections;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class SpamReportsController{private final ReportService reports;private final UserNavigator nav;@FXML private TextField reportSearchField;@FXML private ChoiceBox<com.chatsystem.shared.model.status.ReportStatus>statusChoice;@FXML private ListView<SpamReport>reportList;public SpamReportsController(ReportService r,UserNavigator n){reports=r;nav=n;}@FXML private void initialize(){reportList.setItems(reports.getReports());reportList.setCellFactory(x->new ReportCell());statusChoice.getItems().setAll(com.chatsystem.shared.model.status.ReportStatus.values());}@FXML private void search(){reportList.setItems(FXCollections.observableArrayList(reports.searchReports(reportSearchField.getText(),statusChoice.getValue(),ReportService.ReportSort.NEWEST,0,100)));}@FXML private void create(){nav.showDialog("/fxml/dialogs/new-report.fxml","New report");}@FXML private void open(){var r=reportList.getSelectionModel().getSelectedItem();if(r!=null)nav.navigate(ViewRequest.report(r.getId()));}}
